new:
        pose.yaw[true] = 0;
    }
#ifdef KFX_ANDROID
    for (int i = 0; i < 2; i++) {
        const struct Camera *dcam = &local_state.camera.destination[i ? CamIV_FrontView : CamIV_Isometric];
        if (dcam->zoom > 0) pose.zoom[i] = dcam->zoom;
        if (pckt->action != PckA_ZoomFromMap) pose.yaw[i] = dcam->rotation_angle_x;
    }
